fn plural_pl(n int) PluralCategory {
	if n == 1 {
		return .one
	}
	mod10 := n % 10
	mod100 := n % 100
	if mod10 >= 2 && mod10 <= 4 && (mod100 < 12 || mod100 > 14) {
		return .few
	}
	return .many
}

